namespace {
struct Audio { std::uint32_t sampleRate {48000}; std::size_t channels {2}; std::vector<std::vector<float>> data {}; };
template<class T> bool read(std::ifstream& stream,T& value){return static_cast<bool>(stream.read(reinterpret_cast<char*>(&value),sizeof(value)));}
bool readWav(const std::string& path,Audio& audio){std::ifstream f(path,std::ios::binary);char tag[4]{};std::uint32_t size{};if(!f.read(tag,4)||std::memcmp(tag,"RIFF",4)!=0||!read(f,size)||!f.read(tag,4)||std::memcmp(tag,"WAVE",4)!=0)return false;std::uint16_t format=0,channels=0,bits=0;std::uint32_t sampleRate=0,dataSize=0;std::vector<char> payload;while(f.read(tag,4)&&read(f,size)){if(std::memcmp(tag,"fmt ",4)==0){read(f,format);read(f,channels);read(f,sampleRate);std::uint32_t byteRate{};std::uint16_t align{};read(f,byteRate);read(f,align);read(f,bits);f.seekg(static_cast<std::streamoff>(size)-16,std::ios::cur);}else if(std::memcmp(tag,"data",4)==0){dataSize=size;payload.resize(size);f.read(payload.data(),size);}else f.seekg(size,std::ios::cur);}if(payload.empty()||channels==0||(format!=1&&format!=3)||(bits!=16&&bits!=32))return false;const std::size_t frames=dataSize/(channels*(bits/8));audio={sampleRate,channels,std::vector<std::vector<float>>(channels,std::vector<float>(frames))};for(std::size_t i=0;i<frames;++i)for(std::size_t c=0;c<channels;++c){const auto* p=payload.data()+(i*channels+c)*(bits/8);if(format==1&&bits==16){std::int16_t v{};std::memcpy(&v,p,2);audio.data[c][i]=static_cast<float>(v)/32768.0f;}else {float v{};std::memcpy(&v,p,4);audio.data[c][i]=std::isfinite(v)?v:0.0f;}}return true;}
bool writeWav(const std::string& path,const Audio& audio){if(audio.data.empty())return false;std::ofstream f(path,std::ios::binary);if(!f)return false;const std::uint16_t format=3,channels=static_cast<std::uint16_t>(audio.channels),bits=32,align=channels*4;const std::uint32_t frames=static_cast<std::uint32_t>(audio.data[0].size()),dataBytes=frames*align,riffBytes=36+dataBytes,byteRate=audio.sampleRate*align;f.write("RIFF",4);f.write(reinterpret_cast<const char*>(&riffBytes),4);f.write("WAVEfmt ",8);const std::uint32_t fmtSize=16;f.write(reinterpret_cast<const char*>(&fmtSize),4);f.write(reinterpret_cast<const char*>(&format),2);f.write(reinterpret_cast<const char*>(&channels),2);f.write(reinterpret_cast<const char*>(&audio.sampleRate),4);f.write(reinterpret_cast<const char*>(&byteRate),4);f.write(reinterpret_cast<const char*>(&align),2);f.write(reinterpret_cast<const char*>(&bits),2);f.write("data",4);f.write(reinterpret_cast<const char*>(&dataBytes),4);for(std::size_t i=0;i<frames;++i)for(std::size_t c=0;c<audio.channels;++c){const float v=std::isfinite(audio.data[c][i])?audio.data[c][i]:0.0f;f.write(reinterpret_cast<const char*>(&v),4);}return static_cast<bool>(f);}
Audio generate(const std::string& kind,const float seconds){Audio a;const std::size_t frames=static_cast<std::size_t>(seconds*a.sampleRate);a.data.assign(2,std::vector<float>(frames));std::mt19937 rng(0x4d414452);std::uniform_real_distribution<float> noise(-1.0f,1.0f);for(std::size_t i=0;i<frames;++i){const float t=static_cast<float>(i)/a.sampleRate;float s=0.0f;if(kind=="noise")s=noise(rng)*0.2f;else if(kind=="impulse")s=i==0?0.8f:0.0f;else if(kind=="vowel")s=0.45f*std::sin(2.0f*std::numbers::pi_v<float>*220.0f*t)+0.30f*std::sin(2.0f*std::numbers::pi_v<float>*880.0f*t)+0.2f*std::sin(2.0f*std::numbers::pi_v<float>*1320.0f*t);else s=0.7f*std::sin(2.0f*std::numbers::pi_v<float>*220.0f*t);a.data[0][i]=s;a.data[1][i]=s*0.8f;}return a;}
float rms(const Audio&a){double s=0;std::size_t n=0;for(const auto&ch:a.data)for(float x:ch){s+=x*x;++n;}return static_cast<float>(std::sqrt(s/std::max<std::size_t>(1,n)));}
}
int main(int argc,char**argv){std::string engine="formant",input,output="madron-output.wav",generateKind="vowel",categoryName="texture-mutation",recipeLoad,recipeSave,performance="balanced";float shift=700.0f,seconds=2.0f;std::uint64_t seed=0x4d414452ull;int intensity=50,complexity=50;bool randomRecipe=false;for(int i=1;i<argc;++i){const std::string arg=argv[i];auto value=[&](){return i+1<argc?std::string(argv[++i]):std::string{};};if(arg=="--engine")engine=value();else if(arg=="--random")randomRecipe=true;else if(arg=="--seed")seed=std::stoull(value());else if(arg=="--category")categoryName=value();else if(arg=="--intensity")intensity=std::stoi(value());else if(arg=="--complexity")complexity=std::stoi(value());else if(arg=="--performance")performance=value();else if(arg=="--load-recipe")recipeLoad=value();else if(arg=="--save-recipe")recipeSave=value();else if(arg=="--input")input=value();else if(arg=="--output")output=value();else if(arg=="--generate")generateKind=value();else if(arg=="--seconds")seconds=std::stof(value());else if(arg=="--shift-cents")shift=std::stof(value());else {std::cerr<<"Usage: madron_render --random --seed N --category name --intensity 0..100 --complexity 0..100 [--performance eco|balanced|extreme] [--load-recipe recipe.json] [--save-recipe recipe.json] --output file.wav\n";return 2;}}
    Audio audio;if(!input.empty()){if(!readWav(input,audio)){std::cerr<<"Unsupported WAV: "<<input<<'\n';return 2;}}else audio=generate(generateKind,seconds);if(audio.channels<1||audio.channels>2){std::cerr<<"Only mono/stereo WAV is supported\n";return 2;}Audio rendered{audio.sampleRate,audio.channels,std::vector<std::vector<float>>(audio.channels,std::vector<float>(audio.data[0].size()))};const madron::dsp::ProcessSpec spec{static_cast<double>(audio.sampleRate),256,audio.channels};
    if(randomRecipe){madron::random::Recipe recipe;if(!recipeLoad.empty()){std::ifstream stream(recipeLoad);std::stringstream text;text<<stream.rdbuf();std::string error;auto loaded=madron::random::deserializeRecipeJson(text.str(),&error);if(!loaded){std::cerr<<"Invalid recipe: "<<error<<'\n';return 2;}recipe=*loaded;}else{auto category=madron::random::RecipeGenerator::parseCategory(categoryName);if(!category){std::cerr<<"Unknown category\n";return 2;}const auto mode=performance=="eco"?madron::random::PerformanceMode::Eco:performance=="extreme"?madron::random::PerformanceMode::Extreme:madron::random::PerformanceMode::Balanced;recipe=madron::random::RecipeGenerator{}.generate({{seed},*category,static_cast<std::uint8_t>(std::clamp(intensity,0,100)),static_cast<std::uint8_t>(std::clamp(complexity,0,100)),mode,{}});}if(!recipeSave.empty()){std::ofstream stream(recipeSave);stream<<madron::random::serializeRecipeJson(recipe);}
        madron::random::ValidationResult error;auto graph=madron::random::GraphCompiler{}.compile(recipe.graph,{spec,32},&error);if(!graph){std::cerr<<"Graph compile failed: "<<error.message<<'\n';return 1;}std::array<const float*,2> in{};std::array<float*,2> out{};for(std::size_t offset=0;offset<audio.data[0].size();offset+=256){const auto n=std::min<std::size_t>(256,audio.data[0].size()-offset);for(std::size_t c=0;c<audio.channels;++c){in[c]=audio.data[c].data()+offset;out[c]=rendered.data[c].data()+offset;}if(graph->process({in.data(),audio.channels,n},{out.data(),audio.channels,n})!=madron::dsp::ProcessResult::Ok){std::cerr<<"Graph process failed\n";return 1;}}if(!writeWav(output,rendered)){std::cerr<<"Cannot write: "<<output<<'\n';return 1;}std::cout<<"recipe="<<madron::random::RecipeGenerator::categoryName(recipe.category)<<" seed="<<recipe.seed.value<<" graph="<<graph->summary()<<" latency="<<graph->latencySamples()<<" rms="<<rms(rendered)<<" output="<<output<<'\n';return 0;}
    madron::formant::FormantShifter formant;madron::cepstral::CepstralMorph cepstral;madron::timbre::TimbreResynth timbre;if(engine=="formant"){formant.prepare(spec);formant.setParameters({shift,10.0f,1.0f});}else if(engine=="cepstral"){cepstral.prepare(spec);cepstral.setParameters({madron::cepstral::FFTSize::N1024,0.7f,0.7f,0.5f,madron::cepstral::PhaseMode::Normal});}else if(engine=="timbre"){timbre.prepare(spec);timbre.setParameters({shift,250.0f,1.0f,1,0.0f});}else {std::cerr<<"Unknown engine\n";return 2;}
    std::array<const float*,2> in{};std::array<float*,2> out{};for(std::size_t offset=0;offset<audio.data[0].size();offset+=256){const auto n=std::min<std::size_t>(256,audio.data[0].size()-offset);for(std::size_t c=0;c<audio.channels;++c){in[c]=audio.data[c].data()+offset;out[c]=rendered.data[c].data()+offset;}const madron::dsp::AudioBufferView iv{in.data(),audio.channels,n};const madron::dsp::MutableAudioBufferView ov{out.data(),audio.channels,n};madron::dsp::ProcessResult result{};if(engine=="formant")result=formant.process(iv,ov);else if(engine=="cepstral")result=cepstral.process(iv,ov);else result=timbre.process(iv,ov);if(result!=madron::dsp::ProcessResult::Ok){std::cerr<<"DSP process failed\n";return 1;}}
    if(!writeWav(output,rendered)){std::cerr<<"Cannot write: "<<output<<'\n';return 1;}std::cout<<"engine="<<engine<<" samples="<<rendered.data[0].size()<<" rms="<<rms(rendered)<<" output="<<output<<'\n';return 0;}
